#include <string.h>

#define ARRAY_MAX 100
#define NUM_DIGIT 9
#define NUM_DIGIT_TH_POWER_OF_TEN 1000000000

typedef struct{
           int length;
           long data[ARRAY_MAX];
        }MP;

void set(MP*, const char[]);
void print(const MP*);
void add(const MP*, const MP*, MP*);

