/* 多倍長整数の出力 */
void print(const MP *num){
   int i;

   printf("%ld", num->data[num->length - 1]);
   for(［d］){
      /* ゼロ詰めして必ず9けたを表示する。 */
      printf("%09ld", num->data[i]);
   }
