/* 二つの多倍長整数の加算 */
void add(const MP *a, const MP *b, MP *c){
   int i;
   int i_max;

   if(a->length > b->length){
      i_max = a->length;
   }else{
      i_max = b->length;
   }
   c->data[0] = 0;

   for(i = 0; i < i_max; i++){
      if(i < a->length) c->data[i] += a->data[i];
      if(i < b->length) c->data[i] += b->data[i];

      if(c->data[i] >= NUM_DIGIT_TH_POWER_OF_TEN){  /* ← α */
         c->data[i + 1] = 1;                       /* ← β */
         c->data[i] -= NUM_DIGIT_TH_POWER_OF_TEN;
      }else{
         c->data[i + 1] = 0;
      }
   }
   if(c->data[i] == 0){
      c->length = i;
   }else{
      c->length = i + 1;
   }
}

